const categoryLabels={well_heads:'井头',well_paths:'井轨迹',well_logs:'测井 LAS',checkshots:'Checkshot',well_tops:'井顶',core:'岩心标定',interpretations:'解释结论',seismic_3d:'3D 地震',seismic_2d:'2D 地震',horizons:'层位',faults:'断层',polygons:'Polygon',production:'生产数据',other:'其他资料'};
const expandedTreeCategories=new Set();
const treeCatalogCache=new Map();
const treeCategorySearch=new Map();
const treeSearchDebounce={};

function applyTheme(theme){
  document.documentElement.dataset.theme=theme;
  localStorage.setItem('geo-theme',theme);
  const button=document.querySelector('#theme-toggle');
  if(button){const light=theme==='light';button.querySelector('span').textContent=light?'☾':'☀';button.querySelector('b').textContent=light?'深色':'浅色'}
  const hubButton=document.querySelector('#hub-theme-toggle');if(hubButton)hubButton.textContent=theme==='light'?'☾':'☀';
  requestAnimationFrame(()=>{if(state.activePage==='project'){drawProjectMap();drawProject3d()}if(state.activePage==='wells'&&state.wellView==='map')drawWellDistribution();if(state.activePage==='map')drawMap();if(state.curveDistribution)drawCurveDistribution(state.curveDistribution);if(state.relationshipSearch)drawRelationshipChart(state.relationshipSearch)});
}
document.querySelector('#theme-toggle').onclick=()=>applyTheme(document.documentElement.dataset.theme==='light'?'dark':'light');
applyTheme(document.documentElement.dataset.theme||'dark');

function identityEvidenceCell(files,label){
  if(!files?.length)return `<span class="identity-missing">缺 ${esc(label)}</span>`;
  return `<div class="identity-file-stack">${files.slice(0,2).map(file=>`<span class="identity-file-item">${file.catalog_id?`<button type="button" class="catalog-file-link" data-catalog-reveal="${file.catalog_id}" title="${esc(file.file_path||'')}">${esc(file.filename)}</button>`:`<b title="${esc(file.file_path||'')}">${esc(file.filename)}</b>`}<small title="${esc(file.directory||'')}">${esc(file.directory||'目录未记录')}</small></span>`).join('')}${files.length>2?`<span class="identity-file-more">＋${fmt(files.length-2)} 个文件</span>`:''}</div>`;
}
function renderIdentityMatrix(){
  const data=state.identityMatrix;if(!data)return;
  const query=document.querySelector('#identity-matrix-search').value.trim().toUpperCase(),sort=document.querySelector('#identity-matrix-sort').value;
  const haystack=row=>[row.well_name,...row.las,...row.dev,...row.top].map(value=>typeof value==='string'?value:`${value.filename||''} ${value.directory||''}`).join(' ').toUpperCase();
  const rows=(data.rows||[]).filter(row=>!query||haystack(row).includes(query));
  const missing=row=>[row.las,row.dev,row.top].filter(files=>!files.length).length;
  rows.sort((a,b)=>sort==='missing'?missing(b)-missing(a)||a.well_name.localeCompare(b.well_name):sort==='las'?b.las.length-a.las.length||a.well_name.localeCompare(b.well_name):sort==='dev'?b.dev.length-a.dev.length||a.well_name.localeCompare(b.well_name):sort==='top'?b.top.length-a.top.length||a.well_name.localeCompare(b.well_name):a.well_name.localeCompare(b.well_name));
  document.querySelector('#identity-matrix-note').textContent=`显示 ${fmt(rows.length)} / ${fmt(data.total)} 口井${data.filter?.active?' · 已应用井点筛选':''}；文件名可点击定位本地目录`;
  document.querySelector('#identity-matrix-body').innerHTML=rows.map(row=>`<tr><td class="identity-well-name"><b>${esc(row.well_name)}</b></td><td><span class="identity-gap ${missing(row)?'has-gap':'complete'}">${missing(row)?`缺 ${missing(row)} 类`:'齐全'}</span></td><td>${identityEvidenceCell(row.las,'LAS')}</td><td>${identityEvidenceCell(row.dev,'DEV')}</td><td>${identityEvidenceCell(row.top,'Well Top')}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty-state">没有匹配的井类资料证据</div></td></tr>';
  document.querySelectorAll('#identity-matrix-body [data-catalog-reveal]').forEach(button=>button.onclick=()=>revealCatalogItem(button.dataset.catalogReveal,button.dataset.catalogRevealMode||'select',button));
}
async function setIdentityView(view){
  document.querySelectorAll('[data-identity-view]').forEach(button=>button.classList.toggle('active',button.dataset.identityView===view));
  document.querySelector('#identity-view-chart').classList.toggle('hidden',view!=='chart');document.querySelector('#identity-view-matrix').classList.toggle('hidden',view!=='matrix');
  if(view==='matrix'&&!state.identityMatrix){try{state.identityMatrix=await api('/api/well-evidence-matrix');renderIdentityMatrix()}catch(error){toast(error.message,true)}}
}
document.querySelectorAll('[data-identity-view]').forEach(button=>button.onclick=()=>setIdentityView(button.dataset.identityView));
document.querySelector('#identity-matrix-search').oninput=renderIdentityMatrix;document.querySelector('#identity-matrix-sort').onchange=renderIdentityMatrix;

function databaseCategoryOptions(counts){
  const select=document.querySelector('#catalog-category'),current=state.catalogCategory||select.value;
  select.innerHTML='<option value="">全部资料</option>'+counts.map(row=>`<option value="${esc(row.category_key)}">${esc(categoryLabels[row.category_key]||row.category_key)}（${fmt(row.files)}）</option>`).join('');
  select.value=current;
}

async function loadDatabase(options={}){
  if(options.category!==undefined){state.catalogCategory=options.category;state.catalogPage=1}
  if(options.groupId!==undefined){state.catalogGroupId=options.groupId;state.catalogPage=1}
  const category=state.catalogCategory||'',query=document.querySelector('#catalog-search').value.trim(),params=new URLSearchParams({page:state.catalogPage||1,per_page:100});
  if(category)params.set('category',category);if(query)params.set('q',query);if(state.catalogGroupId)params.set('group_id',state.catalogGroupId);
  const data=await api(`/api/catalog?${params}`);state.catalog=data;databaseCategoryOptions(data.counts);renderDatabase(data);return data;
}

function renderDatabase(data){
  const totalFiles=data.counts.reduce((sum,row)=>sum+row.files,0),totalBytes=data.counts.reduce((sum,row)=>sum+row.bytes,0),representatives=data.items.filter(row=>row.representative).length;
  document.querySelector('#database-kpis').innerHTML=[['完整目录索引',totalFiles,'个文件'],['当前结果',data.total,'个对象'],['索引容量',fileSize(totalBytes),'不复制源数据'],['人工资料夹',data.groups.length,'个持久分组']].map(row=>`<div class="database-kpi"><span>${row[0]}</span><strong>${typeof row[1]==='number'?fmt(row[1]):esc(row[1])}</strong><span>${row[2]}</span></div>`).join('');
  const selectedGroup=data.groups.find(group=>group.id===state.catalogGroupId);
  document.querySelector('#catalog-path').textContent=`完整目录索引 / ${state.catalogCategory?(categoryLabels[state.catalogCategory]||state.catalogCategory):'全部资料'}${selectedGroup?' / '+selectedGroup.name:''} · 本页 ${data.items.length} 个${representatives?`，${representatives} 个代表样本`:''}`;
  document.querySelector('#catalog-body').innerHTML=data.items.map(item=>{const displayName=item.display_name||item.filename,translated=item.display_name&&item.display_name!==item.filename;return `<tr draggable="true" data-catalog-item="${item.id}"><td><input type="checkbox" data-catalog-check="${item.id}" aria-label="选择 ${esc(displayName)}"></td><td class="file-cell"><button type="button" class="catalog-file-link" data-catalog-reveal="${item.id}" title="在资源管理器中定位原始文件">${esc(displayName)}</button><span title="${esc(item.file_path)}">${translated?`原文：${esc(item.filename)} · `:''}${esc(item.relative_path)}</span>${item.match_kind?`<small>${esc(item.match_kind)} · ${Math.round((item.match_score||0)*100)}%</small>`:''}</td><td><span class="tag">${esc(categoryLabels[item.category_key]||item.category_key)}</span></td><td title="${esc(item.source_folder)}">${esc(item.source_folder)}</td><td>${esc(item.extension)}</td><td>${fileSize(item.bytes)}</td><td>${item.representative?'<span class="representative-badge">已解析代表</span>':'<span class="index-badge">已建索引</span>'}</td><td>${item.group_name?`<span class="tag">▣ ${esc(item.group_name)}</span>`:'—'}</td></tr>`}).join('')||'<tr class="catalog-empty-row"><td colspan="8"><div>没有匹配的数据对象</div><small>可尝试井号、去掉连字符后的名称或文件扩展名</small></td></tr>';
  document.querySelector('#catalog-page-label').textContent=`第 ${data.page} / ${data.pages} 页 · 共 ${fmt(data.total)} 个对象`;
  document.querySelector('#catalog-prev').disabled=data.page<=1;document.querySelector('#catalog-next').disabled=data.page>=data.pages;
  renderCatalogGroups(data.groups);
  renderDatabaseScopeControls(data);
  bindCatalogDragRows();
  document.querySelectorAll('[data-catalog-reveal]').forEach(button=>button.onclick=event=>{event.preventDefault();event.stopPropagation();revealCatalogItem(button.dataset.catalogReveal,button.dataset.catalogRevealMode||'select',button)});
  requestAnimationFrame(()=>bindResizableTables(document.querySelector('#page-database')));
}

async function revealCatalogItem(itemId,mode='select',trigger=null){
  if(!itemId)return;
  const openFolder=mode==='folder',originalText=trigger?.querySelector('[data-catalog-action]')?.textContent;
  if(trigger){trigger.disabled=true;trigger.classList.add('opening');const action=trigger.querySelector('[data-catalog-action]');if(action)action.textContent='正在打开…'}
  try{
    const result=await api(`/api/catalog/items/${encodeURIComponent(itemId)}/reveal`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:openFolder?'folder':'select'})});
    toast(openFolder?`已打开 ${result.folder}`:result.selected===false?`已打开所在目录；Windows 未能自动选中 ${result.filename}`:`已在本地目录定位 ${result.filename}`);
  }catch(error){toast(error.message,true)}
  finally{if(trigger){trigger.disabled=false;trigger.classList.remove('opening');const action=trigger.querySelector('[data-catalog-action]');if(action&&originalText)action.textContent=originalText}}
}
window.revealCatalogItem=revealCatalogItem;

function renderCatalogGroups(groups){
  const relevant=groups.filter(group=>!state.catalogCategory||group.category_key===state.catalogCategory),el=document.querySelector('#catalog-groups');
  if(!relevant.length){el.innerHTML='<div class="empty-state">尚未创建人工资料夹</div>';return}
  el.innerHTML=relevant.map(group=>`<div class="catalog-group" data-group-drop="${group.id}" data-group-category="${esc(group.category_key)}"><i>▣</i><span><b>${esc(group.name)}</b><small>${esc(categoryLabels[group.category_key]||group.category_key)}</small></span><em>${fmt(group.item_count)}</em><div class="catalog-group-actions"><button type="button" class="ghost" title="重命名资料夹" data-catalog-group-edit="${group.id}">✎</button><button type="button" class="ghost" title="删除资料夹（不会删除原始文件）" data-catalog-group-delete="${group.id}">×</button></div></div>`).join('');
  bindGroupDrops(el);
  el.querySelectorAll('[data-group-drop]').forEach(group=>group.onclick=()=>{state.catalogCategory=group.dataset.groupCategory;state.catalogGroupId=Number(group.dataset.groupDrop);state.catalogPage=1;loadDatabase()});
  el.querySelectorAll('[data-catalog-group-edit]').forEach(button=>button.onclick=event=>{event.stopPropagation();renameCatalogGroup(button.dataset.catalogGroupEdit)});
  el.querySelectorAll('[data-catalog-group-delete]').forEach(button=>button.onclick=event=>{event.stopPropagation();removeCatalogGroup(button.dataset.catalogGroupDelete)});
}

function selectedCatalogIds(fallback){
  const checked=[...document.querySelectorAll('[data-catalog-check]:checked')].map(input=>Number(input.dataset.catalogCheck));
  return checked.length?checked:[Number(fallback)];
}

function bindCatalogDragRows(){
  document.querySelectorAll('[data-catalog-item]').forEach(row=>row.ondragstart=event=>{event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('application/x-geo-items',JSON.stringify(selectedCatalogIds(row.dataset.catalogItem)))});
}

function bindGroupDrops(scope=document){
  scope.querySelectorAll('[data-group-drop]').forEach(group=>{
    group.ondragover=event=>{event.preventDefault();group.classList.add('drag-over')};
    group.ondragleave=()=>group.classList.remove('drag-over');
    group.ondrop=async event=>{event.preventDefault();group.classList.remove('drag-over');let ids=[];try{ids=JSON.parse(event.dataTransfer.getData('application/x-geo-items')||'[]')}catch{}if(!ids.length)return;try{const result=await api('/api/catalog/items/group',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({group_id:Number(group.dataset.groupDrop),item_ids:ids})});toast(`已归类 ${result.assigned} 个数据对象`);treeCatalogCache.clear();await loadDatabase();if(state.project)enhancedRenderProjectTree(state.project.categories||[])}catch(error){toast(error.message,true)}};
  });
}

async function promptCreateGroup(category,parentId=null){
  if(!category){toast('请先选择一个资料类型',true);return}
  const name=prompt(`在“${categoryLabels[category]||category}”下新建资料夹：`);if(!name||!name.trim())return;
  try{await api('/api/catalog/groups',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({category,name:name.trim(),parent_id:parentId})});toast(`已创建资料夹“${name.trim()}”`);treeCatalogCache.clear();state.catalogCategory=category;state.catalogGroupId=null;await loadDatabase();if(state.project)enhancedRenderProjectTree(state.project.categories||[])}catch(error){toast(error.message,true)}
}

async function renameCatalogGroup(groupId){
  const group=(state.catalog?.groups||[]).find(row=>String(row.id)===String(groupId));if(!group)return;
  const name=prompt('资料夹名称：',group.name);if(!name||name.trim()===group.name)return;
  try{await api(`/api/catalog/groups/${group.id}`,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim()})});toast('资料夹已重命名');treeCatalogCache.clear();await loadDatabase();if(state.project)enhancedRenderProjectTree(state.project.categories||[])}catch(error){toast(error.message,true)}
}

async function removeCatalogGroup(groupId){
  const group=(state.catalog?.groups||[]).find(row=>String(row.id)===String(groupId));if(!group)return;
  if(!confirm(`删除资料夹“${group.name}”？\n仅删除本软件中的资料夹归类，不删除任何原始文件。`))return;
  try{await api(`/api/catalog/groups/${group.id}`,{method:'DELETE'});if(String(state.catalogGroupId)===String(group.id))state.catalogGroupId=null;toast('资料夹已删除，原始文件仍保留');treeCatalogCache.clear();await loadDatabase();if(state.project)enhancedRenderProjectTree(state.project.categories||[])}catch(error){toast(error.message,true)}
}

document.querySelector('#catalog-category').onchange=event=>{state.catalogCategory=event.target.value;state.catalogGroupId=null;state.catalogPage=1;loadDatabase()};
let catalogSearchTimer;document.querySelector('#catalog-search').oninput=()=>{clearTimeout(catalogSearchTimer);catalogSearchTimer=setTimeout(()=>{state.catalogPage=1;loadDatabase()},250)};
document.querySelector('#catalog-refresh').onclick=()=>loadDatabase();
document.querySelector('#catalog-prev').onclick=()=>{state.catalogPage=Math.max(1,state.catalogPage-1);loadDatabase()};
document.querySelector('#catalog-next').onclick=()=>{state.catalogPage+=1;loadDatabase()};
document.querySelector('#catalog-new-group').onclick=()=>promptCreateGroup(state.catalogCategory||document.querySelector('#catalog-category').value);
document.querySelector('#catalog-unassign').onclick=async()=>{
  const ids=selectedCatalogIds();if(!ids.length){toast('请先勾选要移出资料夹的数据对象',true);return}
  try{const result=await api('/api/catalog/items/group',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({item_ids:ids})});toast(`已移出 ${fmt(result.unassigned)} 个数据对象；原始文件未变动`);treeCatalogCache.clear();await loadDatabase();if(state.project)enhancedRenderProjectTree(state.project.categories||[])}catch(error){toast(error.message,true)}
};

async function loadTreeCategory(category){
  if(treeCatalogCache.has(category))return treeCatalogCache.get(category);
  const data=await api(`/api/catalog?category=${encodeURIComponent(category)}&per_page=500`);treeCatalogCache.set(category,data);return data;
}
function treeCategoryCacheKey(category,query){
  const safe=treeSearchText(query);
  if(!safe) return category;
  return `${category}::query::${safe}`;
}
async function loadTreeCategoryByQuery(category,query=''){
  const key=treeCategoryCacheKey(category,query);
  if(treeCatalogCache.has(key))return treeCatalogCache.get(key);
  const params=new URLSearchParams({category,per_page:500});
  if(query)params.set('q',query);
  const data=await api(`/api/catalog?${params.toString()}`);treeCatalogCache.set(key,data);return data;
}

function treeSearchText(value){
  return String(value||'').toLowerCase();
}

function treeSearchCompact(value){
  return treeSearchText(value).replace(/[^a-z0-9]/g, '');
}

function treeObjectMatches(item,query){
  if(!query) return true;
  const q=treeSearchText(query);
  const qc=treeSearchCompact(q);
  const filename=treeSearchText(item.filename),display=treeSearchText(item.display_name||item.filename),relative=treeSearchText(item.relative_path),source=treeSearchText(item.source_folder);
  if(`${filename} ${display} ${relative} ${source}`.includes(q)) return true;
  if(!qc) return false;
  return `${treeSearchCompact(filename)} ${treeSearchCompact(display)} ${treeSearchCompact(relative)} ${treeSearchCompact(source)}`.includes(qc);
}

function renderTreeGroup(group,groups,items,query){
  const qc=treeSearchCompact(query);
  const children=groups.filter(item=>item.parent_id===group.id);
  const childRendered=children.map(child=>renderTreeGroup(child,groups,items,query)).filter(Boolean);
  const childViews=childRendered.join('');
  const directItems=items.filter(item=>item.group_id===group.id&&treeObjectMatches(item,query)).map(item=>`<div class="tree-child object" draggable="true" data-tree-item="${item.id}" title="${esc(item.relative_path)}"><span>${esc(item.display_name||item.filename)}</span>${item.representative?'<em>样本</em>':''}</div>`);
  const groupName=treeSearchText(group.name);
  const groupNameMatches=groupName.includes(query)||qc&&treeSearchCompact(groupName).includes(qc);
  const hasMatch=groupNameMatches||childRendered.length||directItems.length;
  if(!hasMatch)return '';
  const empty=query&&(!directItems.length&&!childRendered.length)?'<div class="tree-child tree-empty">未匹配到对象</div>':'';
  return `<div class="tree-child group" draggable="false" data-group-drop="${group.id}" data-group-category="${esc(group.category_key)}" title="拖放数据对象到这里；右键继续新建子文件夹"><i class="folder-mark">▣</i><span>${esc(group.name)}</span><em>${fmt(group.item_count)}</em></div>${childViews}${directItems.join('')}${empty}`;
}

function renderTreeChildren(category,groups,items){
  const query=treeSearchText(treeCategorySearch.get(category));
  if(!items.length){return `<div class="tree-child tree-empty">没有匹配到对象</div>`;}
  const rootGroups=groups.filter(group=>!group.parent_id);
  const groupViews=rootGroups.map(group=>renderTreeGroup(group,groups,items,query)).filter(Boolean).join('');
  const rootItems=items.filter(item=>!item.group_id&&treeObjectMatches(item,query)).map(item=>`<div class="tree-child object" draggable="true" data-tree-item="${item.id}" title="${esc(item.relative_path)}"><span>${esc(item.display_name||item.filename)}</span>${item.representative?'<em>样本</em>':''}</div>`);
  const rows=`${groupViews}${rootItems.join('')}`;
  if(!rows && query){
    return `<div class="tree-child tree-empty">未匹配到对象</div>`;
  }
  return `${rows}${!query&&items.length>40?`<div class="tree-child tree-more" data-tree-more="${esc(category)}">查看全部 ${fmt(items.length)} 个…</div>`:''}`;
}

async function toggleTreeCategory(category){
  if(expandedTreeCategories.has(category)){expandedTreeCategories.delete(category);enhancedRenderProjectTree(state.project.categories||[]);return}
  expandedTreeCategories.add(category);enhancedRenderProjectTree(state.project.categories||[]);
  const query=treeSearchText(treeCategorySearch.get(category));
  try{await loadTreeCategoryByQuery(category,query);enhancedRenderProjectTree(state.project.categories||[])}catch(error){toast(error.message,true)}
}

function enhancedRenderProjectTree(categories){
  if(!state.treeCatalogBootstrap){
    state.treeCatalogBootstrap='loading';
    api('/api/catalog?per_page=20').then(data=>{state.treeCatalogBootstrap=data;enhancedRenderProjectTree(state.project?.categories||categories)}).catch(()=>{state.treeCatalogBootstrap='failed'});
  }
  if(state.treeCatalogBootstrap&&typeof state.treeCatalogBootstrap==='object'){
    const known=new Set(categories.map(row=>row.key));
    categories=[...categories,...state.treeCatalogBootstrap.counts.filter(row=>!known.has(row.category_key)).map(row=>({key:row.category_key,label:categoryLabels[row.category_key]||row.category_key,files:row.files,bytes:row.bytes}))];
  }
  const el=document.querySelector('#project-tree');
  el.innerHTML=categories.map(row=>{
    const expanded=expandedTreeCategories.has(row.key);
    const query=treeSearchText(treeCategorySearch.get(row.key)||'');
    const cacheKey=treeCategoryCacheKey(row.key,query);
    const resolvedData=treeCatalogCache.get(cacheKey);
    const groups=(resolvedData?.groups||[]).filter(group=>group.category_key===row.key);
    const shouldLoad=expanded && !resolvedData;
    if(shouldLoad){loadTreeCategoryByQuery(row.key,query).then(()=>enhancedRenderProjectTree(state.project?.categories||categories)).catch(()=>{});}
    const children=!expanded?'':`<div class="tree-children"><div class="tree-search-row"><div class="search tree-search"><span>⌕</span><input type="text" placeholder="筛选当前类别（含）" data-tree-category-search="${esc(row.key)}" value="${esc(query)}"/></div></div>${!resolvedData?'<div class="tree-child">正在载入…</div>':`${renderTreeChildren(row.key,groups,resolvedData.items)}`}</div>`;
    return `<div class="tree-row ${row.files?'active':''} ${expanded?'expanded':''}" data-tree-category="${esc(row.key)}"><i class="tree-chevron">▶</i><i class="tree-icon">${cockpitIcons[row.key]||'DT'}</i><span><b>${esc(row.label)}</b><span>${fileSize(row.bytes)}</span></span><em>${projectFmt(row.files)}</em></div>${children}`;
  }).join('');
  el.querySelectorAll('[data-tree-category]').forEach(row=>{row.onclick=()=>toggleTreeCategory(row.dataset.treeCategory);row.ondblclick=()=>{state.catalogCategory=row.dataset.treeCategory;state.catalogGroupId=null;navigate('database')};row.oncontextmenu=event=>{event.preventDefault();promptCreateGroup(row.dataset.treeCategory)}});
  el.querySelectorAll('[data-tree-category-search]').forEach(input=>{
    input.onclick=event=>event.stopPropagation();
    input.onmousedown=event=>event.stopPropagation();
    input.oninput=()=>{
      const key=input.dataset.treeCategorySearch;
      if(!key)return;
      clearTimeout(treeSearchDebounce[key]);
      treeSearchDebounce[key]=setTimeout(()=>{
        const value=treeSearchText(input.value);
        if(value)treeCategorySearch.set(key,value);else treeCategorySearch.delete(key);
        expandedTreeCategories.add(key);
        void (async()=>{try{await loadTreeCategoryByQuery(key,value);enhancedRenderProjectTree(state.project.categories||[])}catch(error){toast(error.message,true)}})();
      },180);
    };
  });
  el.querySelectorAll('[data-tree-item]').forEach(item=>item.ondragstart=event=>event.dataTransfer.setData('application/x-geo-items',JSON.stringify([Number(item.dataset.treeItem)])));
  el.querySelectorAll('[data-tree-more]').forEach(item=>item.onclick=()=>{state.catalogCategory=item.dataset.treeMore;state.catalogGroupId=null;navigate('database')});
  el.querySelectorAll('[data-group-drop]').forEach(group=>{group.onclick=event=>{event.stopPropagation();state.catalogCategory=group.dataset.groupCategory;state.catalogGroupId=Number(group.dataset.groupDrop);navigate('database')};group.oncontextmenu=event=>{event.preventDefault();event.stopPropagation();promptCreateGroup(group.dataset.groupCategory,Number(group.dataset.groupDrop))}});
  bindGroupDrops(el);
  bindTreeHoverCards(el);
}

renderProjectTree=enhancedRenderProjectTree;
if(state.project)enhancedRenderProjectTree(state.project.categories||[]);

// Tree cards are fetched only after a deliberate hover and cached client-side.
const treeCardCache=new Map(),treeHoverCard=document.querySelector('#tree-hover-card');let treeHoverTimer=null,treeHideTimer=null,treeCardCurrent=null;
function invalidateTreeCards(){treeCardCache.clear()}
window.invalidateTreeCards=invalidateTreeCards;
function treeMetricValue(metric){if(metric.label.includes('大小')&&typeof metric.value==='number')return fileSize(metric.value);return typeof metric.value==='number'?fmt(metric.value):esc(metric.value)}
function renderTreeHoverCard(data,anchor){
  treeCardCurrent={data,anchor};
  const maxCurve=Math.max(1,...(data.curves||[]).map(row=>row.wells||0));
  const path=data.file_path || data.subtitle || '';
  treeHoverCard.innerHTML=`
    <header>
      <div>
        <span>${esc(categoryLabels[data.category]||data.category)}</span>
        <b>${esc(data.title)}</b>
      </div>
      <button data-tree-card-refresh title="刷新资料卡">↻</button>
    </header>
    <p class="tree-card-path-row" title="${esc(path)}">
      ${data.file_path ? `<button type="button" class="tree-card-path" data-tree-card-open="${esc(data.item_id || '')}" title="${esc(path)}">${esc(path)}</button>` : `<span>${esc(data.subtitle)}</span>`}
    </p>
    <div class="tree-card-metrics">${(data.metrics||[]).map(row=>`<div><span>${esc(row.label)}</span><b>${treeMetricValue(row)}</b></div>`).join('')}</div>
    ${data.highlights?.length?`<div class="tree-card-highlights">${data.highlights.map(value=>`<span>${esc(value)}</span>`).join('')}</div>`:''}
    ${data.curves?.length?`<section><div class="mini-head"><h3>代表曲线统计</h3><span>井数 / MD 范围</span></div>${data.curves.map(row=>`<div class="tree-card-curve"><b>${esc(row.name)}</b><div><i style="width:${(row.wells||0)/maxCurve*100}%"></i></div><span>${fmt(row.wells)}井 · ${row.start==null?'—':`${fmt(row.start,0)}–${fmt(row.stop,0)}`}</span></div>`).join('')}</section>`:''}
    <footer><span>${fmt(data.files)} 个文件 · ${fileSize(data.bytes)} · ${fmt(data.folders)} 个目录</span><em>缓存于 ${esc((data.generated_at||'').replace('T',' ').slice(11,19))}</em></footer>
  `;
  treeHoverCard.classList.remove('hidden');
  const rect=anchor.getBoundingClientRect(),cardHeight=treeHoverCard.getBoundingClientRect().height,top=Math.max(12,Math.min(window.innerHeight-cardHeight-12,rect.top));
  treeHoverCard.style.left=`${Math.max(12,Math.min(window.innerWidth-350,rect.right+10))}px`;
  treeHoverCard.style.top=`${top}px`;
  const refresh=treeHoverCard.querySelector('[data-tree-card-refresh]');
  const openPath=treeHoverCard.querySelector('[data-tree-card-open]');
  refresh.onclick=()=>{const key=anchor.dataset.treeItem?`item:${anchor.dataset.treeItem}`:`category:${anchor.dataset.treeCategory}`;treeCardCache.delete(key);scheduleTreeCard(anchor,0)};
  if(openPath){
    openPath.onclick=()=>revealCatalogItem(openPath.dataset.treeCardOpen,'select',openPath);
  }
}
