function scheduleTreeCard(anchor,delay=700){clearTimeout(treeHoverTimer);clearTimeout(treeHideTimer);treeHoverTimer=setTimeout(()=>showTreeCard(anchor),delay)}
function scheduleTreeCardHide(){clearTimeout(treeHoverTimer);clearTimeout(treeHideTimer);treeHideTimer=setTimeout(()=>treeHoverCard.classList.add('hidden'),180)}
function bindTreeHoverCards(scope){scope.querySelectorAll('[data-tree-category],[data-tree-item]').forEach(anchor=>{anchor.onmouseenter=()=>scheduleTreeCard(anchor);anchor.onmouseleave=scheduleTreeCardHide})}
treeHoverCard.onmouseenter=()=>clearTimeout(treeHideTimer);treeHoverCard.onmouseleave=scheduleTreeCardHide;

