document.querySelector('#well-distribution-canvas').onclick=event=>{const canvas=event.currentTarget,map=canvas._wellMap;if(!map)return;const rect=canvas.getBoundingClientRect(),x=event.clientX-rect.left,y=event.clientY-rect.top;let nearest=null,distance=11;for(const row of map.rows){const current=Math.hypot(map.tx(row.x)-x,map.ty(row.y)-y);if(current<distance){distance=current;nearest=row}}if(nearest)showWell(nearest.id)};
