// Persistent .nvt workspace controls.
const workspaceDialog=document.querySelector('#workspace-dialog');
async function loadWorkspaceState(){const info=await api('/api/workspace');state.workspace=info;document.querySelector('#workspace-path').value=info.path||info.suggested_path||'';document.querySelector('#workspace-state').innerHTML=info.active?`<span class="status ready">已打开</span><div><b>${esc(info.project_title||info.name)}</b><small>${esc(info.path)} · 格式 v${info.format_version} · 应用 ${esc(info.app_version||'—')}</small></div>`:`<span class="status">尚未保存</span><div><b>临时分析状态</b><small>保存后会建立同名 .nvt 工区文件夹</small></div>`;if(info.project_title){document.querySelector('#sidebar-project-name').textContent=info.project_title;document.querySelector('#breadcrumb-project-title').textContent=info.project_title}return info}
document.querySelector('#workspace-button').onclick=async()=>{workspaceDialog.showModal();try{await loadWorkspaceState()}catch(error){toast(error.message,true)}};document.querySelector('.workspace-close').onclick=()=>{state.openWorkspaceFromHub=false;workspaceDialog.close()};
document.querySelector('#save-workspace').onclick=async()=>{const button=document.querySelector('#save-workspace');button.disabled=true;button.textContent='保存中…';try{const info=await api('/api/workspace/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:document.querySelector('#workspace-path').value.trim()})});toast(`工区已保存：${info.name}`);await loadWorkspaceState();sessionStorage.setItem('geo-enter-project','1');setTimeout(()=>location.reload(),700)}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='保存当前工区'}};
document.querySelector('#open-workspace').onclick=async()=>{const button=document.querySelector('#open-workspace');button.disabled=true;button.textContent='打开中…';try{const info=await api('/api/workspace/open',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:document.querySelector('#workspace-path').value.trim()})});if(info.migrated)alert(`工区已从格式 v${info.previous_version} 原位升级到 v${info.format_version}。按设置未创建自动备份。`);toast(`已打开工区：${info.name}`);if(state.openWorkspaceFromHub)sessionStorage.setItem('geo-enter-project','1');setTimeout(()=>location.reload(),500)}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='打开 .nvt 工区'}};
const workspaceRelocation=document.querySelector('#workspace-relocation'),workspaceOldPrefix=document.querySelector('#workspace-old-prefix'),workspaceNewPrefix=document.querySelector('#workspace-new-prefix'),workspaceRelocationStatus=document.querySelector('#workspace-relocation-status'),workspaceApplyPaths=document.querySelector('#workspace-apply-paths');
let workspacePathPreview=null;
function resetWorkspacePathPreview(){workspacePathPreview=null;workspaceApplyPaths.disabled=true;workspaceRelocationStatus.className='workspace-relocation-status';workspaceRelocationStatus.textContent='先预览匹配的路径，再确认更改。'}
workspaceOldPrefix.oninput=resetWorkspacePathPreview;workspaceNewPrefix.oninput=resetWorkspacePathPreview;
document.querySelector('#workspace-change-path').onclick=async()=>{if(!state.workspace?.active){try{await loadWorkspaceState()}catch(error){toast(error.message,true);return}}if(!state.workspace?.active){toast('请先打开需要更改路径的 .nvt 工区',true);return}workspaceRelocation.classList.toggle('hidden');if(workspaceRelocation.classList.contains('hidden'))return;const oldDrive=/^[A-Za-z]:\\/.exec(state.workspace.source_root||'')?.[0]||'',newDrive=/^[A-Za-z]:\\/.exec(state.workspace.path||'')?.[0]||'';workspaceOldPrefix.value=oldDrive&&newDrive&&oldDrive.toLowerCase()!==newDrive.toLowerCase()?oldDrive:(state.workspace.source_root||'');workspaceNewPrefix.value=oldDrive&&newDrive&&oldDrive.toLowerCase()!==newDrive.toLowerCase()?newDrive:'';resetWorkspacePathPreview()};
document.querySelector('#workspace-preview-paths').onclick=async()=>{const button=document.querySelector('#workspace-preview-paths'),old_prefix=workspaceOldPrefix.value.trim(),new_prefix=workspaceNewPrefix.value.trim();button.disabled=true;workspaceRelocationStatus.className='workspace-relocation-status';workspaceRelocationStatus.textContent='正在核验新目录与工区内部引用…';try{const result=await api('/api/workspace/relocate-paths',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({old_prefix,new_prefix})});workspacePathPreview={old_prefix,new_prefix};workspaceApplyPaths.disabled=false;workspaceRelocationStatus.className='workspace-relocation-status ready';workspaceRelocationStatus.innerHTML=`原始目录：${esc(result.source_root)}<br>新目录：${esc(result.target_root)}<br>将更新 ${fmt(result.database_count)} 处数据库引用、${fmt(result.file_count)} 个工区配置文件；抽查资料 ${fmt(result.sample_found)} / ${fmt(result.sample_checked)} 个可访问。`}catch(error){resetWorkspacePathPreview();workspaceRelocationStatus.className='workspace-relocation-status failed';workspaceRelocationStatus.textContent=error.message}finally{button.disabled=false}};
workspaceApplyPaths.onclick=async()=>{const old_prefix=workspaceOldPrefix.value.trim(),new_prefix=workspaceNewPrefix.value.trim();if(!workspacePathPreview||workspacePathPreview.old_prefix!==old_prefix||workspacePathPreview.new_prefix!==new_prefix){resetWorkspacePathPreview();return}workspaceApplyPaths.disabled=true;workspaceApplyPaths.textContent='更改中…';try{const result=await api('/api/workspace/relocate-paths',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({old_prefix,new_prefix,apply:true})});toast(`工区路径已更新：${result.target_root}`);sessionStorage.setItem('geo-enter-project','1');setTimeout(()=>location.reload(),500)}catch(error){workspaceRelocationStatus.className='workspace-relocation-status failed';workspaceRelocationStatus.textContent=error.message;toast(error.message,true)}finally{workspaceApplyPaths.textContent='确认更改路径'}};

// Background import with upload progress, parser progress and ETA.
let currentImportJob=null,jobPollTimer=null;
function resetImportButtons(){const upload=document.querySelector('#upload-form button[type=submit]'),path=document.querySelector('#path-form button[type=submit]'),preflight=document.querySelector('#import-preflight-selected'),ofm=document.querySelector('#mount-ofm-mdb'),reanalyze=document.querySelector('#reanalyze-ofm-mdb');upload.disabled=false;upload.textContent='开始解析并入库';path.disabled=false;path.textContent='直接导入所选路径';if(preflight){preflight.disabled=false;preflight.textContent='导入已选文件'}if(ofm){ofm.disabled=false;ofm.textContent='挂载并分析 MDB'}if(reanalyze){reanalyze.disabled=false;reanalyze.textContent='重新分析当前 MDB'}}
function showImportProgress(percent,stage,file,eta,files=[]){const panel=document.querySelector('#import-progress-panel');panel.classList.remove('hidden');const value=Math.max(0,Math.min(100,Math.round(percent)));document.querySelector('#import-progress-percent').textContent=`${value}%`;document.querySelector('#import-progress-fill').style.width=`${value}%`;document.querySelector('#import-progress-stage').textContent=stage||'处理中';document.querySelector('#import-progress-file').textContent=file||'—';document.querySelector('#import-progress-eta').textContent=eta==null?'估算剩余时间：计算中':`估算剩余时间：${eta<60?eta+' 秒':Math.ceil(eta/60)+' 分钟'}`;document.querySelector('#import-progress-files').innerHTML=files.map(row=>`<div class="progress-file"><span class="status ${row.status==='complete'?'ready':row.status==='failed'?'failed':''}">${esc(row.name)}</span><div><i style="width:${Math.round((row.progress||0)*100)}%"></i></div><em>${Math.round((row.progress||0)*100)}%</em></div>`).join('');const ofmButton=document.querySelector('#mount-ofm-mdb'),ofmStatus=document.querySelector('#ofm-mount-status');if(ofmButton?.disabled&&ofmStatus){ofmStatus.textContent=`${stage||'分析 MDB'} · ${value}%`;ofmStatus.className='ofm-mount-state ready'}}
function renderJobCenter(jobs){const rows=Array.isArray(jobs)?jobs:[jobs],el=document.querySelector('#job-center-list');document.querySelector('#job-center-status').textContent=rows.length?`${rows.filter(row=>row.status==='running'||row.status==='queued').length} 个运行中`:'暂无任务';el.className=rows.length?'':'empty-state';el.innerHTML=rows.map(row=>`<div class="job-card"><div><b>${row.kind==='import'?'数据导入':'分析任务'}</b><span>${esc(row.stage)}</span></div><strong>${row.percent}%</strong><div class="mini-progress"><i style="width:${row.percent}%"></i></div><small>${esc(row.current_file||row.status)}</small></div>`).join('')||'导入和分析任务会显示在这里'}
async function pollImportJob(jobId){clearTimeout(jobPollTimer);try{const job=await api(`/api/import-jobs/${jobId}`);currentImportJob=job;showImportProgress(30+job.progress*70,job.stage,job.current_file,job.eta_seconds,job.files);renderJobCenter([job]);if(['complete','partial','failed'].includes(job.status)){resetImportButtons();renderImportResults({results:job.results,errors:job.errors});toast(job.status==='complete'?`成功导入 ${job.results.length} 个文件`:`任务完成：${job.results.length} 成功，${job.errors.length} 失败`,job.status==='failed');if(job.results.some(row=>row.data_type==='well_head')&&state.productionClustering)state.productionClustering.data=null;invalidateTreeCards();await Promise.all([loadOverview(),loadGlobalFilterState()]);if(state.activePage==='production')await loadProduction();return}jobPollTimer=setTimeout(()=>pollImportJob(jobId),600)}catch(error){resetImportButtons();toast(error.message,true)}}
function uploadImportJob(form){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/import-jobs');xhr.upload.onprogress=event=>{if(event.lengthComputable)showImportProgress(event.loaded/event.total*30,'上传到本地工区缓存','正在传输文件',null)};xhr.onload=()=>{let data={};try{data=JSON.parse(xhr.responseText)}catch{}xhr.status>=200&&xhr.status<300?resolve(data):reject(new Error(data.error||`请求失败 ${xhr.status}`))};xhr.onerror=()=>reject(new Error('上传连接失败'));xhr.send(new FormData(form))})}
document.querySelector('#upload-form').onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type=submit]');button.disabled=true;button.textContent='上传中…';try{const job=await uploadImportJob(event.currentTarget);currentImportJob=job;button.textContent='后台解析中';pollImportJob(job.id)}catch(error){toast(error.message,true);button.disabled=false;button.textContent='开始解析并入库'}};
document.querySelector('#path-form').onsubmit=async event=>{event.preventDefault();const options=formOptions(event.currentTarget),paths=document.querySelector('#local-paths').value.split(/\r?\n/).map(value=>value.trim()).filter(Boolean),button=event.currentTarget.querySelector('button[type=submit]');if(!paths.length){toast('请选择或输入本地文件 / 文件夹路径',true);return}button.disabled=true;button.textContent='创建任务…';try{showImportProgress(1,'检查本机路径',paths[0],null);const job=await api('/api/import-jobs/path',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...options,paths})});currentImportJob=job;button.textContent='后台导入中';pollImportJob(job.id)}catch(error){toast(error.message,true);button.disabled=false;button.textContent='直接导入所选路径'}};
async function pickLocalFolder(targetId,append=false){const target=document.querySelector(`#${targetId}`),initial=(target.value||'').split(/\r?\n/).filter(Boolean).at(-1)||'',trigger=document.activeElement,originalText=trigger?.tagName==='BUTTON'?trigger.textContent:'';if(trigger?.tagName==='BUTTON'){trigger.disabled=true;trigger.textContent='正在打开…'}try{const result=await api('/api/local-folder-picker',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({initial})});if(result.path){target.value=append&&target.value.trim()?`${target.value.trim()}\n${result.path}`:result.path;target.dispatchEvent(new Event('input',{bubbles:true}))}}catch(error){toast(error.message,true)}finally{if(trigger?.tagName==='BUTTON'){trigger.disabled=false;trigger.textContent=originalText}}}
document.querySelector('#pick-preflight-folder').onclick=()=>pickLocalFolder('preflight-path');document.querySelector('#pick-import-folder').onclick=()=>pickLocalFolder('local-paths',true);document.querySelector('#pick-ofm-folder').onclick=()=>pickLocalFolder('ofm-mdb-path');
document.querySelector('#production-export-to-folder').onclick=async()=>{const button=document.querySelector('#production-export-to-folder'),status=document.querySelector('#production-export-status');button.disabled=true;button.textContent='选择文件夹…';try{const picked=await api('/api/local-folder-picker',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({initial:''})});if(!picked.path){status.textContent='已取消选择，未写出文件。';return}button.textContent='正在生成 ZIP…';status.textContent=`正在整理标准汇总、字段目录与全部 MDB 原表，目标：${picked.path}`;const result=await api('/api/production/export-to-folder',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder:picked.path})});status.innerHTML=`已导出：<b title="${esc(result.path)}">${esc(result.path)}</b> · ${typeof fileSize==='function'?fileSize(result.bytes):fmt(result.bytes)} · 含数据可用性清单`;toast('OFM 完整拆分 ZIP 已写入指定目录')}catch(error){status.textContent=`导出失败：${error.message}`;toast(error.message,true)}finally{button.disabled=false;button.textContent='指定导出路径'}};
document.querySelector('#mount-ofm-mdb').onclick=async()=>{const button=document.querySelector('#mount-ofm-mdb'),path=document.querySelector('#ofm-mdb-path').value.trim(),status=document.querySelector('#ofm-mount-status');if(!path){toast('请选择 OFM MDB 文件或其所在文件夹',true);return}button.disabled=true;button.textContent='建立挂载任务…';status.textContent='正在检查本地路径';status.className='ofm-mount-state';try{const job=await api('/api/import-jobs/path',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({paths:[path],data_type:'production',batch:'OFM MDB',version:'Access read-only'})});currentImportJob=job;button.textContent='后台分析中';pollImportJob(job.id)}catch(error){toast(error.message,true);button.disabled=false;button.textContent='挂载并分析 MDB';status.textContent='挂载失败';status.className='ofm-mount-state warning'}};
document.querySelector('#reanalyze-ofm-mdb').onclick=async()=>{const button=document.querySelector('#reanalyze-ofm-mdb'),sourceId=button.dataset.ofmSourceId,status=document.querySelector('#ofm-mount-status');if(!sourceId){toast('请先挂载一个当前可访问的 MDB',true);return}button.disabled=true;button.textContent='重新建立分析任务…';status.textContent='准备按新版规则重新分析';status.className='ofm-mount-state ready';try{const job=await api('/api/ofm/reanalyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_id:Number(sourceId)})});currentImportJob=job;button.textContent='后台重新分析中';pollImportJob(job.id)}catch(error){toast(error.message,true);button.disabled=false;button.textContent='重新分析当前 MDB';status.textContent='重新分析失败';status.className='ofm-mount-state warning'}};
document.querySelectorAll('[data-production-panel]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-production-panel]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('.production-panel').forEach(panel=>panel.classList.toggle('active',panel.id===`production-panel-${button.dataset.productionPanel}`));if(button.dataset.productionPanel==='statistics'&&typeof openProductionStatisticsPanel==='function')openProductionStatisticsPanel()});
api('/api/import-jobs').then(renderJobCenter).catch(()=>{});

// Recursive folder preflight: metadata only, then hand selected files to the existing import job.
let preflightData=null,preflightType='all';const preflightSelected=new Set();
function preflightFilteredFiles(){if(!preflightData)return[];const query=document.querySelector('#preflight-search').value.trim().toUpperCase();return preflightData.files.filter(row=>(preflightType==='all'||row.type_key===preflightType)&&(!query||`${row.name} ${row.relative_path}`.toUpperCase().includes(query)))}
function renderPreflightGroups(){const groups=preflightData?.groups||[],el=document.querySelector('#preflight-groups');el.innerHTML=`<button class="${preflightType==='all'?'active':''}" data-preflight-type="all"><span><b>全部文件</b><small>${fmt(preflightData.total_files)} 个 · ${fileSize(preflightData.total_bytes)}</small></span><em>${fmt(preflightData.importable_files)} 可导入</em></button>`+groups.map(row=>`<button class="${preflightType===row.type_key?'active':''}" data-preflight-type="${esc(row.type_key)}"><span><b>${esc(row.type_label)}</b><small>${row.extensions.slice(0,3).map(item=>`${esc(item.extension)} × ${fmt(item.count)}`).join(' · ')}</small></span><em>${fmt(row.count)} / ${fmt(row.importable_count)}</em></button>`).join('');el.querySelectorAll('[data-preflight-type]').forEach(button=>button.onclick=()=>{preflightType=button.dataset.preflightType;renderPreflightGroups();renderPreflightFiles()})}
function renderPreflightFiles(){const rows=preflightFilteredFiles(),visible=rows.slice(0,400),el=document.querySelector('#preflight-files-body');el.innerHTML=visible.map(row=>`<tr class="${row.importable?'':'unsupported'}"><td><input type="checkbox" data-preflight-file="${row.id}" ${preflightSelected.has(row.id)?'checked':''} ${row.importable?'':'disabled'}></td><td class="file-cell"><b>${esc(row.name)}</b><span title="${esc(row.path)}">${esc(row.relative_path)}</span></td><td><span class="tag">${esc(row.type_label)}</span></td><td>${esc(row.extension)}</td><td>${fileSize(row.bytes)}</td><td>${row.importable?'<span class="status ready">可批量导入</span>':'<span class="muted">仅预统计 / 目录索引</span>'}</td></tr>`).join('')+(rows.length>visible.length?`<tr><td colspan="6" class="preflight-more">当前条件共 ${fmt(rows.length)} 个文件；为保持流畅仅渲染前 ${fmt(visible.length)} 个，批量选择仍作用于全部。</td></tr>`:'')||'<tr><td colspan="6" class="empty-state">没有匹配文件</td></tr>';el.querySelectorAll('[data-preflight-file]').forEach(input=>input.onchange=()=>{const id=Number(input.dataset.preflightFile);input.checked?preflightSelected.add(id):preflightSelected.delete(id);renderPreflightSelection()});renderPreflightSelection()}
function renderPreflightSelection(){const bytes=(preflightData?.files||[]).filter(row=>preflightSelected.has(row.id)).reduce((sum,row)=>sum+row.bytes,0);document.querySelector('#preflight-selected-count').textContent=`已选 ${fmt(preflightSelected.size)} · ${fileSize(bytes)}`}
function renderPreflight(data){preflightData=data;preflightType='all';preflightSelected.clear();document.querySelector('#preflight-result').classList.remove('hidden');document.querySelector('#preflight-state').textContent=`${data.scanned_at.replace('T',' ').slice(0,19)} 完成`;document.querySelector('#preflight-metrics').innerHTML=[['文件总数',data.total_files,'个'],['嵌套目录',data.folder_count,'个'],['总容量',fileSize(data.total_bytes),'仅读元数据'],['可批量导入',data.importable_files,'个']].map(row=>`<div><span>${row[0]}</span><b>${typeof row[1]==='number'?fmt(row[1]):esc(row[1])}</b><small>${row[2]}</small></div>`).join('');renderPreflightGroups();renderPreflightFiles()}
document.querySelector('#run-preflight').onclick=async()=>{const button=document.querySelector('#run-preflight'),path=document.querySelector('#preflight-path').value.trim();if(!path){toast('请输入本地文件夹路径',true);return}button.disabled=true;button.textContent='正在统计…';document.querySelector('#preflight-state').textContent='递归读取目录元数据';try{const data=await api('/api/preflight/folder',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})});renderPreflight(data);toast(`预统计完成：${fmt(data.total_files)} 个文件，${fmt(data.importable_files)} 个可导入`)}catch(error){document.querySelector('#preflight-state').textContent='扫描失败';toast(error.message,true)}finally{button.disabled=false;button.textContent='快速预统计'}};
document.querySelector('#preflight-search').oninput=renderPreflightFiles;
document.querySelector('#preflight-select-visible').onclick=()=>{preflightFilteredFiles().filter(row=>row.importable).forEach(row=>preflightSelected.add(row.id));renderPreflightFiles()};
document.querySelector('#preflight-clear').onclick=()=>{preflightSelected.clear();renderPreflightFiles()};
document.querySelector('#import-preflight-selected').onclick=async()=>{const selected=(preflightData?.files||[]).filter(row=>preflightSelected.has(row.id)&&row.importable),button=document.querySelector('#import-preflight-selected');if(!selected.length){toast('请先选择至少一个可导入文件',true);return}const options=formOptions(document.querySelector('#preflight-import-form'));button.disabled=true;button.textContent='创建批量任务…';try{showImportProgress(1,'接收预统计选择',`${selected.length} 个本地文件`,null);const job=await api('/api/import-jobs/path',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...options,paths:selected.map(row=>row.path)})});currentImportJob=job;button.textContent='后台导入中';pollImportJob(job.id);toast(`已提交 ${selected.length} 个文件到后台任务`)}catch(error){toast(error.message,true);button.disabled=false;button.textContent='导入已选文件'}};

// Curve workbench interactions.
function renderCurveWorkbench(){const workbench=state.curveWorkbench;if(!workbench)return;const options=workbench.curves.map(row=>`<option value="${esc(row.mnemonic)}">${esc(row.mnemonic)} · ${fmt(row.well_count)} 井</option>`).join('');const curveA=document.querySelector('#curve-a'),curveB=document.querySelector('#curve-b'),oldA=curveA.value,oldB=curveB.value;curveA.innerHTML=options;curveB.innerHTML=options;curveA.value=oldA||workbench.curves[0]?.mnemonic||'';curveB.value=oldB||workbench.curves[1]?.mnemonic||workbench.curves[0]?.mnemonic||'';renderCurveTypes(workbench);renderSamplingAudit(workbench);populateFocusTypes(workbench);populateDistributionFromWorkbench(workbench);if(document.querySelector('#curve-panel-focus').classList.contains('active'))loadCurveFocus();if(document.querySelector('#curve-panel-distribution').classList.contains('active'))loadCurveFilterState().catch(()=>{})}

// Coverage rows drill into the exact well roster immediately. Numeric samples
// remain lazy: only the selected mnemonic is read from representative LAS files.
const curveDetailWindow=document.querySelector('#curve-detail-window'),curveDetailHead=document.querySelector('#curve-detail-head'),curveDetailCanvas=document.querySelector('#curve-detail-histogram');
let curveDetailRequest=0,curveDetailDrag=null,curveDetailHistogramData=null;
function curveDetailRow(mnemonic){return (state.curves||[]).find(row=>row.mnemonic===mnemonic)}
function curveDetailRange(row){return row?.value_min!=null&&row?.value_max!=null?`${distributionNumber(row.value_min)} – ${distributionNumber(row.value_max)}`:'按需读取'}
function curveDetailWellRows(row){return row?.well_details?.length?row.well_details:(row?.wells||[]).map(wellKey=>({well_key:wellKey,well_name:wellKey,filenames:[],steps:[],units:[],sample_count:0,start_md:null,stop_md:null,value_min:null,value_max:null}))}
function renderCurveDetailWells(row){const query=document.querySelector('#curve-detail-well-search').value.trim().toUpperCase(),all=curveDetailWellRows(row),rows=all.filter(item=>`${item.well_name} ${item.well_key} ${(item.filenames||[]).join(' ')}`.toUpperCase().includes(query));document.querySelector('#curve-detail-well-count').textContent=query?`${fmt(rows.length)} / ${fmt(all.length)} 口井`:`${fmt(all.length)} 口井 · 当前井点筛选口径`;document.querySelector('#curve-detail-wells').innerHTML=rows.map(item=>{const depth=item.start_md==null||item.stop_md==null?'深度范围待补充':`${distributionNumber(item.start_md)}–${distributionNumber(item.stop_md)} MD`,files=(item.filenames||[]).length;return `<button type="button" class="curve-detail-well" data-curve-detail-well="${esc(item.well_key)}" title="${esc((item.filenames||[]).join(' · ')||'代表 LAS 文件名未记录')}"><span><b>${esc(item.well_name||item.well_key)}</b><span>${depth} · ${fmt(files)} 个 LAS · ${fmt(item.sample_count||0)} 样点</span></span><em>井详情 →</em></button>`}).join('')||'<div class="empty-state">没有匹配的井名</div>';document.querySelectorAll('[data-curve-detail-well]').forEach(button=>button.onclick=()=>showWell(`project:${button.dataset.curveDetailWell}`))}
function curveDetailMetrics(row){const assignment=row.assignment||{},suggestion=row.suggestion||{},type=(state.curveWorkbench?.types||[]).find(item=>item.type_key===(assignment.type_key||suggestion.type_key)),units=(row.units||[]).join?.(' / ')||row.units||'未标注';document.querySelector('#curve-detail-metrics').innerHTML=[["覆盖井",fmt(row.well_count),"当前井点筛选"],["LAS 文件",fmt(row.file_count),"代表画像"],["单位",units,"不同单位不应混绘"],["采样间隔",row.steps?.length?row.steps.map(value=>distributionNumber(value)).join(' / '):'—',"STEP"],["已知值域",curveDetailRange(row),type?.name||'未分类']].map((item,index)=>`<div><span>${esc(item[0])}</span><b ${index===4?'id="curve-detail-range-metric"':''}>${esc(item[1])}</b><small>${esc(item[2])}</small></div>`).join('')}
async function copyCurveDetailWells(row){const names=curveDetailWellRows(row).map(item=>item.well_name||item.well_key).join('\n');try{await navigator.clipboard.writeText(names);toast(`已复制 ${fmt(curveDetailWellRows(row).length)} 个井名`)}catch{const area=document.createElement('textarea');area.value=names;document.body.appendChild(area);area.select();document.execCommand('copy');area.remove();toast(`已复制 ${fmt(curveDetailWellRows(row).length)} 个井名`)}}
function drawCurveDetailHistogram(group){curveDetailHistogramData=group;const canvas=curveDetailCanvas,empty=document.querySelector('#curve-detail-chart-empty'),tooltip=document.querySelector('#curve-histogram-tooltip');if(!group?.series?.length){canvas._bars=[];empty.classList.remove('hidden');tooltip.classList.add('hidden');return}const series=group.series[0],bins=series.histogram||[],rect=canvas.getBoundingClientRect(),ratio=window.devicePixelRatio||1;canvas.width=Math.max(1,Math.floor(rect.width*ratio));canvas.height=Math.max(1,Math.floor(rect.height*ratio));const c=canvas.getContext('2d');c.scale(ratio,ratio);c.clearRect(0,0,rect.width,rect.height);const light=document.documentElement.dataset.theme==='light',left=45,right=rect.width-14,top=18,bottom=rect.height-31,maxRatio=Math.max(.01,...bins.map(bin=>Number(bin.ratio)||0)),span=Math.max(1e-12,group.display_max-group.display_min),x=value=>left+(right-left)*(value-group.display_min)/span,y=value=>bottom-(bottom-top)*value/maxRatio;c.font='7px Segoe UI';c.strokeStyle=light?'#dbe5df':'#25443a';c.fillStyle=light?'#71857c':'#708a80';for(let index=0;index<=4;index++){const yy=top+(bottom-top)*index/4,ratioValue=maxRatio*(4-index)/4;c.beginPath();c.moveTo(left,yy);c.lineTo(right,yy);c.stroke();c.fillText(`${fmt(ratioValue*100,1)}%`,5,yy+3)}for(let index=0;index<=4;index++){const value=group.display_min+span*index/4,xx=x(value);c.fillText(distributionNumber(value),Math.max(left,Math.min(right-38,xx-15)),rect.height-9)}const gap=Math.min(2.5,Math.max(.5,(right-left)/Math.max(1,bins.length)*.12));canvas._bars=bins.map(bin=>{const x0=x(bin.x0)+gap,x1=x(bin.x1)-gap,yy=y(bin.ratio),width=Math.max(1,x1-x0),height=Math.max(1,bottom-yy);const gradient=c.createLinearGradient(x0,yy,x0,bottom);gradient.addColorStop(0,light?'#16735f':'#b9e94b');gradient.addColorStop(1,light?'#69a891':'#278c77');c.fillStyle=gradient;c.fillRect(x0,yy,width,height);return {x:x0,y:yy,width,height,bin}});empty.classList.add('hidden');canvas.onmousemove=event=>{const bounds=canvas.getBoundingClientRect(),px=event.clientX-bounds.left,py=event.clientY-bounds.top,bar=(canvas._bars||[]).find(item=>px>=item.x&&px<=item.x+item.width&&py>=item.y&&py<=bottom);if(!bar){tooltip.classList.add('hidden');return}tooltip.innerHTML=`<b>${distributionNumber(bar.bin.x0)} – ${distributionNumber(bar.bin.x1)} ${esc(group.unit)}</b><span>${fmt(bar.bin.count)} 个样点 · ${fmt(bar.bin.ratio*100,2)}%</span>`;tooltip.classList.remove('hidden');tooltip.style.left=`${Math.min(rect.width-155,Math.max(6,px+10))}px`;tooltip.style.top=`${Math.max(6,py-48)}px`};canvas.onmouseleave=()=>tooltip.classList.add('hidden')}
async function loadCurveDetailHistogram(row,requestId){const empty=document.querySelector('#curve-detail-chart-empty'),range=document.querySelector('#curve-detail-histogram-range');empty.className='curve-detail-chart-empty curve-detail-loading';empty.textContent='正在按需读取代表 LAS 数值样点…';range.textContent='正在读取…';curveDetailHistogramData=null;try{const result=await api('/api/curve-distribution',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'single_curve',mnemonics:[row.mnemonic],bins:24,coverage_detail:true})});if(requestId!==curveDetailRequest)return;const group=result.groups?.[0],series=group?.series?.[0];if(!group||!series){empty.className='curve-detail-chart-empty';empty.textContent=result.meta?.unavailable_count?'该曲线可确认井覆盖，但代表 LAS 暂无可读取数值样点；可在“采样与重采样评估”中重建画像。':'当前井点筛选范围内没有有效数值样点。';range.textContent='暂无有效数值样本';drawCurveDetailHistogram(null);return}range.textContent=`${distributionNumber(group.full_min)} – ${distributionNumber(group.full_max)} ${group.unit}`;const metric=document.querySelector('#curve-detail-range-metric');if(metric)metric.textContent=`${distributionNumber(group.full_min)} – ${distributionNumber(group.full_max)}`;const meta=result.meta||{},sampled=meta.source_sampled?` · 代表抽样 ${fmt(meta.source_files_read)}/${fmt(meta.source_files_candidate)} 井`:'';document.querySelector('#curve-detail-subtitle').textContent=`${fmt(row.well_count)} 口井 · ${fmt(series.stats.count)} 个抽样点 · ${group.unit}${sampled}`;drawCurveDetailHistogram(group)}catch(error){if(requestId!==curveDetailRequest)return;empty.className='curve-detail-chart-empty';empty.textContent=`数值分布读取失败：${error.message}`;range.textContent='读取失败';drawCurveDetailHistogram(null)}}
function openCurveDetail(mnemonic,view='wells'){const row=curveDetailRow(mnemonic);if(!row)return;state.curveDetailMnemonic=mnemonic;document.querySelector('#curve-detail-title').textContent=`${mnemonic} · 曲线详情`;document.querySelector('#curve-detail-subtitle').textContent=`${fmt(row.well_count)} 口井 · 覆盖井清单与数值分布`;document.querySelector('#curve-detail-well-search').value='';curveDetailMetrics(row);renderCurveDetailWells(row);document.querySelector('#curve-detail-well-search').oninput=()=>renderCurveDetailWells(row);document.querySelector('#curve-detail-copy-wells').onclick=()=>copyCurveDetailWells(row);curveDetailWindow.classList.remove('hidden');const requestId=++curveDetailRequest;loadCurveDetailHistogram(row,requestId);if(view==='distribution')setTimeout(()=>document.querySelector('#curve-detail-histogram-section').scrollIntoView({behavior:'smooth',block:'nearest'}),60)}
function bindCurveCoverageInteractions(){document.querySelectorAll('[data-curve-detail]').forEach(element=>element.onclick=event=>{event.stopPropagation();openCurveDetail(element.dataset.curveDetail,element.dataset.curveDetailView||'wells')})}
document.querySelector('#curve-detail-close').onclick=()=>{curveDetailRequest++;curveDetailWindow.classList.add('hidden')};curveDetailHead.onpointerdown=event=>{if(event.target.closest('button'))return;const rect=curveDetailWindow.getBoundingClientRect();curveDetailDrag={dx:event.clientX-rect.left,dy:event.clientY-rect.top};curveDetailHead.setPointerCapture(event.pointerId)};curveDetailHead.onpointermove=event=>{if(!curveDetailDrag)return;const left=Math.max(0,Math.min(window.innerWidth-curveDetailWindow.offsetWidth,event.clientX-curveDetailDrag.dx)),top=Math.max(0,Math.min(window.innerHeight-70,event.clientY-curveDetailDrag.dy));curveDetailWindow.style.left=`${left}px`;curveDetailWindow.style.top=`${top}px`;curveDetailWindow.style.right='auto'};curveDetailHead.onpointerup=()=>curveDetailDrag=null;new ResizeObserver(()=>{if(curveDetailHistogramData&&!curveDetailWindow.classList.contains('hidden'))requestAnimationFrame(()=>drawCurveDetailHistogram(curveDetailHistogramData))}).observe(document.querySelector('.curve-detail-chart'));
document.querySelectorAll('[data-curve-panel]').forEach(button=>button.onclick=()=>{document.querySelectorAll('[data-curve-panel]').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('.curve-panel').forEach(panel=>panel.classList.toggle('active',panel.id===`curve-panel-${button.dataset.curvePanel}`));if(button.dataset.curvePanel==='focus'&&!state.curveFocus)loadCurveFocus();if(button.dataset.curvePanel==='distribution'){loadCurveFilterState().then(()=>state.curveDistribution&&requestAnimationFrame(()=>drawCurveDistribution(state.curveDistribution))).catch(()=>{})}});
function curveChip(row){const assignment=row.assignment||{},suggestion=row.suggestion||{};return `<span class="curve-chip" draggable="true" data-curve-chip="${esc(row.mnemonic)}" title="${esc(suggestion.reason||'')}"><b>${esc(row.mnemonic)}</b><em>${fmt(row.well_count)}井 · ${assignment.status==='confirmed'?'人工确认':suggestion.type_key?'系统建议':'未分类'}</em></span>`}
function renderCurveTypes(workbench){const byType={};workbench.curves.forEach(row=>{const key=(row.assignment||{}).type_key||null;(byType[key]??=[]).push(row)});const pending=[...(byType[null]||[]),...(byType.unclassified||[])];document.querySelector('#curve-unclassified').innerHTML=pending.map(curveChip).join('')||'<span class="muted">没有未分类曲线</span>';document.querySelector('#curve-type-grid').innerHTML=workbench.types.filter(type=>type.type_key!=='unclassified').map(type=>`<article class="curve-type-card" data-curve-type-drop="${esc(type.type_key)}" style="--curve-type-color:${esc(type.color)}"><header><i></i><div><b>${esc(type.name)}</b><span>${esc(type.canonical_role||'自定义')} · ${(byType[type.type_key]||[]).length} mnemonic</span></div></header><div>${(byType[type.type_key]||[]).map(curveChip).join('')||'<span class="muted">拖动曲线到这里</span>'}</div></article>`).join('');bindCurveTypeDrag()}
function bindCurveTypeDrag(){document.querySelectorAll('[data-curve-chip]').forEach(chip=>chip.ondragstart=event=>event.dataTransfer.setData('text/x-curve-mnemonic',chip.dataset.curveChip));document.querySelectorAll('[data-curve-type-drop]').forEach(card=>{card.ondragover=event=>{event.preventDefault();card.classList.add('drag-over')};card.ondragleave=()=>card.classList.remove('drag-over');card.ondrop=async event=>{event.preventDefault();card.classList.remove('drag-over');const mnemonic=event.dataTransfer.getData('text/x-curve-mnemonic');if(!mnemonic)return;await api('/api/curve-types/assign',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({mnemonic,type_key:card.dataset.curveTypeDrop})});toast(`${mnemonic} 已人工归入测井类型，并从解释候选池移除`);await Promise.all([loadCurves(),loadInterpretations()])}});const pool=document.querySelector('.curve-unclassified');pool.ondragover=event=>{event.preventDefault();pool.classList.add('drag-over')};pool.ondragleave=()=>pool.classList.remove('drag-over');pool.ondrop=async event=>{event.preventDefault();pool.classList.remove('drag-over');const mnemonic=event.dataTransfer.getData('text/x-curve-mnemonic');if(!mnemonic)return;await api('/api/curve-types/assign',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({mnemonic,type_key:null})});toast(`${mnemonic} 已移回共享待确认池`);await Promise.all([loadCurves(),loadInterpretations()])}}
document.querySelector('#new-curve-type').onclick=async()=>{const name=prompt('新建测井曲线类型名称：');if(!name?.trim())return;const role=prompt('标准角色缩写（可选，例如 PE、TOC）：')||'';await api('/api/curve-types',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name.trim(),role:role.trim()})});toast(`已新建曲线类型“${name.trim()}”`);await loadCurves()};
document.querySelector('#run-curve-compare').onclick=async()=>{const button=document.querySelector('#run-curve-compare');button.disabled=true;button.textContent='比较中…';try{const result=await api('/api/curve-compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({curve_a:document.querySelector('#curve-a').value,curve_b:document.querySelector('#curve-b').value})});renderCurveCompare(result)}catch(error){toast(error.message,true)}finally{button.disabled=false;button.textContent='开始比较'}};
function renderCurveCompare(result){const el=document.querySelector('#curve-compare-result');el.className='curve-compare-result';const list=(title,values,cls)=>`<div class="curve-set ${cls}"><b>${title}</b><strong>${fmt(values.length)}</strong><div>${values.slice(0,80).map(value=>`<span>${esc(value)}</span>`).join('')||'<em>无</em>'}</div></div>`;el.innerHTML=`<div class="curve-set-grid">${list(`仅 ${result.curve_a}`,result.only_a_wells,'only-a')}${list('共同井',result.intersection_wells,'both')}${list(`仅 ${result.curve_b}`,result.only_b_wells,'only-b')}</div><div class="compare-diagnostics"><div><span>共同深度段中位覆盖</span><b>${result.depth_overlap_median==null?'待重建画像':result.depth_overlap_median+'%'}</b></div><div><span>采样间隔</span><b>${result.sampling_same?'一致':'不一致 / 缺失'}</b><small>${result.steps_a.join(', ')||'—'} ⇄ ${result.steps_b.join(', ')||'—'}</small></div><div><span>分布相似度</span><b>${result.distribution_similarity==null?'待重建画像':Math.round(result.distribution_similarity*100)+'%'}</b></div><div><span>可替代性</span><b>${esc(result.replacement_hint)}</b></div></div><div class="callout wide"><strong>标准化提示</strong><p>${esc(result.standardization_hint)}</p></div>`}

// Focus merge builds one logical curve per well while preserving every source curve.
const focusRuleDescriptions={
  multiple:'仅显示同一口井内、已归入当前类型的候选曲线达到 2 条及以上的井。用于排查 GR / GR_1、不同批次或重复导入的“可合并对象”；最终曲线仍由覆盖深度、有效样点完整度、标准 mnemonic、单位、数值范围和采样间隔综合优选。',
  all:'仅显示同时拥有当前类型全部候选 mnemonic 的井。例如当前类型下识别到 GR、GR_1、CGR，则该井必须三者都有才进入。它最严格，适合做同批次或多命名曲线的完整横向对比，结果井数通常最少。',
  any:'只要该井拥有当前类型下任意一条候选曲线就显示。它用于建立最宽口径的“每井一条最终曲线”清单；只有一条候选的井也会被保留，但没有可供合并的重复曲线。'
};
const focusOutputNames={};
function syncFocusOutputMnemonic(){
  const typeSelect=document.querySelector('#focus-type'),input=document.querySelector('#focus-output-mnemonic');
  if(!typeSelect||!input)return;
  const type=(state.curveWorkbench?.types||[]).find(row=>row.type_key===typeSelect.value);
  input.value=focusOutputNames[typeSelect.value]||type?.name||'';
}
function syncFocusRuleExplanation(){const select=document.querySelector('#focus-rule'),help=document.querySelector('#focus-rule-help');if(!select||!help)return;const text=focusRuleDescriptions[select.value]||'';select.title=text;help.title=text;help.setAttribute('aria-label',`井集合规则说明：${text}`)}
function populateFocusTypes(workbench){const select=document.querySelector('#focus-type'),old=select.value,counts={};workbench.curves.forEach(row=>{const key=(row.assignment||{}).type_key||(row.suggestion||{}).type_key;if(key&&key!=='unclassified')counts[key]=(counts[key]||0)+1});const rows=workbench.types.filter(row=>row.type_key!=='unclassified'&&counts[row.type_key]);select.innerHTML=rows.map(row=>`<option value="${esc(row.type_key)}">${esc(row.name)} · ${fmt(counts[row.type_key])} 个 mnemonic</option>`).join('')||'<option value="">没有已归类曲线</option>';select.value=rows.some(row=>row.type_key===old)?old:(rows.some(row=>row.type_key==='gamma_ray')?'gamma_ray':rows[0]?.type_key||'');syncFocusOutputMnemonic();state.curveFocus=null;document.querySelector('#focus-label').textContent=select.value?'选择规则后生成逐井方案':'请先在“曲线类型”中完成归类'}
function focusVisibleRows(){const data=state.curveFocus;if(!data)return[];const rule=document.querySelector('#focus-rule').value,query=document.querySelector('#focus-well-search').value.trim().toUpperCase();return data.rows.filter(row=>(rule==='any'||(rule==='multiple'&&row.candidate_count>1)||(rule==='all'&&row.has_all))&&(!query||row.well_name.toUpperCase().includes(query)))}
function focusCandidateCard(row,candidate){const duplicate=candidate.near_duplicates?.length?'<span class="focus-duplicate" title="深度覆盖、采样间隔和摘要分布高度接近；仍需同深度逐点复核">疑似重复</span>':'';return `<div class="focus-candidate ${candidate.selected?'selected':''} ${candidate.excluded?'excluded':''}" title="${esc(candidate.filename)} · ${esc(candidate.reasons.join('；'))}"><div><b>${esc(candidate.mnemonic)}</b><strong>${fmt(candidate.score,1)}</strong></div><span>${candidate.start==null?'MD —':`MD ${fmt(candidate.start,0)}–${fmt(candidate.stop,0)}`} · 完整 ${fmt(candidate.completeness,0)}%</span><small>${esc(candidate.filename)}</small>${duplicate}<footer><button class="ghost" data-focus-action="select" data-focus-well="${esc(row.well_key)}" data-focus-candidate="${esc(candidate.candidate_id)}">${candidate.selected?'已采用':'指定'}</button><button class="ghost ${candidate.excluded?'restore':'remove'}" data-focus-action="exclude" data-focus-well="${esc(row.well_key)}" data-focus-candidate="${esc(candidate.candidate_id)}">${candidate.excluded?'恢复':'排除'}</button></footer></div>`}
function renderCurveFocus(){const data=state.curveFocus;if(!data)return;const rows=focusVisibleRows(),summary=data.summary;document.querySelector('#focus-metrics').innerHTML=[['画像井',summary.wells,'井点筛选后'],['候选 mnemonic',summary.candidate_mnemonics,`主单位 ${data.modal_unit||'—'}`],['多候选井',summary.multi_candidate_wells,'需要重点复核'],['人工调整',summary.manual_wells,'已保存到 .nvt'],['当前显示',rows.length,document.querySelector('#focus-rule').selectedOptions[0]?.textContent||'']].map(row=>`<div><span>${row[0]}</span><b>${fmt(row[1])}</b><small>${esc(row[2])}</small></div>`).join('');document.querySelector('#focus-label').textContent=`${data.type.name} · ${fmt(rows.length)} / ${fmt(summary.wells)} 口井 · ${esc(data.profile_source||'代表 LAS 画像')}（${fmt(data.sample_wells)} 口样本）`;document.querySelector('#focus-head').innerHTML=`<tr><th class="focus-well-column">井名</th>${data.mnemonics.map(name=>`<th>${esc(name)}</th>`).join('')}<th class="focus-final-column">最终目标曲线</th></tr>`;document.querySelector('#focus-body').innerHTML=rows.map(row=>`<tr><td class="focus-well-column"><b>${esc(row.well_name)}</b><span>${fmt(row.candidate_count)} 条候选 · ${fmt(row.mnemonic_count)} 种名称</span></td>${data.mnemonics.map(name=>{const candidates=row.candidates.filter(candidate=>candidate.mnemonic===name);return `<td>${candidates.map(candidate=>focusCandidateCard(row,candidate)).join('')||'<span class="focus-missing">—</span>'}</td>`}).join('')}<td class="focus-final-column">${row.selected?`<div class="focus-final"><b>${esc(row.selected.mnemonic)}</b><span>${fmt(row.selected.score,1)} 分 · ${row.decision_status==='manual'?(row.manual_selected_candidate_id?'人工指定':'人工约束后自动'):'自动优选'}</span><small>${esc(row.selected.filename)}</small></div>`:'<span class="status failed">无可用候选</span>'}${row.decision_status==='manual'?`<button class="ghost" data-focus-reset="${esc(row.well_key)}">恢复全自动</button>`:''}</td></tr>`).join('')||'<tr><td colspan="99" class="empty-state">当前规则下没有井</td></tr>';document.querySelectorAll('[data-focus-action]').forEach(button=>button.onclick=()=>changeFocusDecision(button.dataset.focusWell,button.dataset.focusCandidate,button.dataset.focusAction));document.querySelectorAll('[data-focus-reset]').forEach(button=>button.onclick=()=>resetFocusDecision(button.dataset.focusReset))}
async function loadCurveFocus(){const typeKey=document.querySelector('#focus-type').value,button=document.querySelector('#run-curve-focus');if(!typeKey){document.querySelector('#focus-label').textContent='没有可生成方案的已归类曲线';return}button.disabled=true;button.textContent='生成中…';document.querySelector('#focus-label').textContent='正在按井计算候选完整度与自动优选分数…';try{state.curveFocus=await api(`/api/curve-focus?type_key=${encodeURIComponent(typeKey)}`);renderCurveFocus()}catch(error){toast(error.message,true);document.querySelector('#focus-label').textContent='方案生成失败'}finally{button.disabled=false;button.textContent='生成 / 刷新方案'}}
async function changeFocusDecision(wellKey,candidateId,action){const row=state.curveFocus?.rows.find(item=>item.well_key===wellKey),candidate=row?.candidates.find(item=>item.candidate_id===candidateId);if(!row||!candidate)return;const excluded=new Set(row.candidates.filter(item=>item.excluded).map(item=>item.candidate_id));let selected=row.manual_selected_candidate_id||null;if(action==='select'){excluded.delete(candidateId);selected=candidateId}else if(candidate.excluded){excluded.delete(candidateId)}else{excluded.add(candidateId);if(selected===candidateId)selected=null}try{await api('/api/curve-focus/decision',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({type_key:state.curveFocus.type.type_key,well_key:wellKey,selected_candidate_id:selected,excluded_candidate_ids:[...excluded]})});toast(action==='select'?`${row.well_name} 已人工指定 ${candidate.mnemonic}`:`${candidate.mnemonic} 已${candidate.excluded?'恢复':'从逻辑方案排除'}；原始 LAS 未改变`);await loadCurveFocus()}catch(error){toast(error.message,true)}}
async function resetFocusDecision(wellKey){try{await api('/api/curve-focus/decision',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({type_key:state.curveFocus.type.type_key,well_key:wellKey})});toast('已恢复全自动优选');await loadCurveFocus()}catch(error){toast(error.message,true)}}
async function exportCurveFocusCurves(){
  const button=document.querySelector('#export-curve-focus');
  if(!state.curveFocus?.type?.type_key){
    toast('请先生成聚焦合并方案', true);
    return;
  }
  const typeKey=state.curveFocus.type.type_key;
  const outputMnemonic=document.querySelector('#focus-output-mnemonic')?.value.trim();
  if(!outputMnemonic){toast('请输入最终目标曲线名',true);return}
  button.disabled=true;
  const previous=button.textContent;
  button.textContent='选择导出目录…';
  try{
    const picked=await api('/api/local-folder-picker',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({initial:''})
    });
    if(!picked?.path){
      toast('已取消导出');
      return;
    }
    button.textContent='导出中…';
    const response=await api('/api/curve-focus/export',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({type_key:typeKey,output_mnemonic:outputMnemonic,output_dir:picked.path})
    });
    if(response?.path){
      const skipped=Number(response.skipped||0);
      const exported=Number(response.exported||0);
      const details = (response.manifest || []).filter(row => row?.status !== 'ok');
      const failSamples = details.slice(0,3).map(row => `${row.well_name||row.well_key}: ${row.reason || '未知原因'}`).join('；');
      let message = `聚焦合并曲线导出完成 · 已导出 ${exported} / ${fmt(exported+skipped)}；跳过 ${fmt(skipped)} 口。详见：${response.path}`;
      if (details.length) {
        message += `；失败示例：${failSamples}`;
      }
      toast(message);
    }else{
      throw new Error('导出返回异常：缺少输出目录路径');
    }
  }catch(error){
    toast(error.message,true);
  }finally{
    button.disabled=false;
    button.textContent=previous;
  }
}
