// Filename translation is deliberately local and display-only.  It never
// opens a source file and never writes back to the selected directory.
const directoryTranslationState={folder:'',page:1,query:''};
function renderDirectoryTranslation(data){
  const body=document.querySelector('#directory-translation-body'),summary=document.querySelector('#directory-translation-summary'),page=document.querySelector('#directory-translation-page');
  const items=data.items||[];
  body.innerHTML=items.map(item=>`<tr><td title="${esc(item.relative_path)}">${esc(item.original_name)}</td><td>${esc(item.display_name)}</td><td title="${esc(item.relative_path)}">${esc(item.relative_path)}</td><td>${esc(item.extension||'—')}</td></tr>`).join('')||'<tr><td colspan="4" class="empty-state">没有匹配的目录对象</td></tr>';
  const changed=fmt(data.translated_files||0),total=fmt(data.total||0);
  summary.textContent=`已建立 ${changed} / ${total} 个中文显示名；可按原文、中文或路径继续筛选。${data.updated_at?` 最近更新：${String(data.updated_at).replace('T',' ').slice(0,19)}`:''}`;
  page.textContent=`第 ${data.page} / ${data.pages} 页 · 当前匹配 ${fmt(data.total)} 个文件`;
  document.querySelector('#directory-translation-prev').disabled=data.page<=1;
  document.querySelector('#directory-translation-next').disabled=data.page>=data.pages;
}
async function loadDirectoryTranslation(){
  const input=document.querySelector('#directory-translation-folder'),folder=input.value.trim();
  if(!folder){document.querySelector('#directory-translation-summary').textContent='请选择目录。目录翻译只会记录软件内显示别名，不会修改本地源文件。';return}
  directoryTranslationState.folder=folder;
  const params=new URLSearchParams({folder,page:String(directoryTranslationState.page||1),per_page:'160'});
  if(directoryTranslationState.query)params.set('q',directoryTranslationState.query);
  try{renderDirectoryTranslation(await api(`/api/directory-translations?${params}`))}catch(error){
    if(error.message.includes('请先指定已翻译的目录')){document.querySelector('#directory-translation-summary').textContent='该目录尚未生成显示别名。点击“生成软件内中文显示名”开始。';return}
    throw error;
  }
}
async function runDirectoryTranslation(){
  const folder=document.querySelector('#directory-translation-folder').value.trim(),button=document.querySelector('#directory-translation-run'),status=document.querySelector('#directory-translation-status');
  if(!folder){toast('请先选择需要翻译的本地文件夹',true);return}
  button.disabled=true;button.textContent='正在遍历文件名…';status.textContent='仅读取目录项和文件名，不读取文件内容，也不会重命名源文件。';
  try{
    const result=await api('/api/directory-translations/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder,custom_glossary:document.querySelector('#directory-translation-glossary').value})});
    directoryTranslationState.folder=folder;directoryTranslationState.page=1;directoryTranslationState.query='';document.querySelector('#directory-translation-search').value='';
    status.textContent=`已处理 ${fmt(result.total_files)} 个文件，其中 ${fmt(result.translated_files)} 个获得中文显示名；原始文件未改动。`;
    treeCatalogCache.clear();state.treeCatalogBootstrap=null;
    if(state.project)enhancedRenderProjectTree(state.project.categories||[]);
    await loadDirectoryTranslation();toast('目录翻译显示别名已更新');
  }catch(error){status.textContent=`目录翻译失败：${error.message}`;toast(error.message,true)}finally{button.disabled=false;button.textContent='生成软件内中文显示名'}
}
document.querySelector('#directory-translation-pick').onclick=()=>pickLocalFolder('directory-translation-folder');
document.querySelector('#directory-translation-run').onclick=runDirectoryTranslation;
