async function uniqueDirectoryFileName(directoryHandle,filename){
  const dot=filename.lastIndexOf('.'),base=dot>0?filename.slice(0,dot):filename,extension=dot>0?filename.slice(dot):'';let candidate=filename,index=2;
  while(true){try{await directoryHandle.getFileHandle(candidate);candidate=`${base}_${index}${extension}`;index+=1}catch(error){if(error?.name==='NotFoundError')return candidate;throw error}}
}
