// Interpretation types are separate database objects and can be created from either related view.
function interpretationChip(row){const assignment=row.assignment||{},suggestion=row.suggestion||{},origin=row.origin==='las_curve'?'LAS 字段':'解释文件';return `<span class="interpretation-chip" draggable="true" data-interpretation-chip="${esc(row.attribute_name)}" title="${esc(`${origin} · ${suggestion.reason||''}`)}"><b>${esc(row.attribute_name)}</b><em>${fmt(row.well_count)}井 · ${origin} · ${assignment.status==='confirmed'?'人工确认':suggestion.type_key?'系统建议':'未分类'}</em></span>`}
