function bindInterpretationTypeDrag(){document.querySelectorAll('[data-interpretation-chip]').forEach(chip=>chip.ondragstart=event=>event.dataTransfer.setData('text/x-interpretation-attribute',chip.dataset.interpretationChip));document.querySelectorAll('[data-interpretation-type-drop]').forEach(card=>{card.ondragover=event=>{event.preventDefault();card.classList.add('drag-over')};card.ondragleave=()=>card.classList.remove('drag-over');card.ondrop=async event=>{event.preventDefault();card.classList.remove('drag-over');const attribute_name=event.dataTransfer.getData('text/x-interpretation-attribute');if(!attribute_name)return;await api('/api/interpretation-types/assign',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({attribute_name,type_key:card.dataset.interpretationTypeDrop})});toast(`${attribute_name} 已归入解释结论类型，并从测井候选池移除`);await Promise.all([loadInterpretations(),loadCurves()])}});const pool=document.querySelector('.interpretation-pool');pool.ondragover=event=>{event.preventDefault();pool.classList.add('drag-over')};pool.ondragleave=()=>pool.classList.remove('drag-over');pool.ondrop=async event=>{event.preventDefault();pool.classList.remove('drag-over');const attribute_name=event.dataTransfer.getData('text/x-interpretation-attribute');if(!attribute_name)return;await api('/api/interpretation-types/assign',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({attribute_name,type_key:null})});toast(`${attribute_name} 已移回共享待确认池`);await Promise.all([loadInterpretations(),loadCurves()])}}
