  document.querySelector('#hub-overview').innerHTML=[['项目历史',projects.length,'个分析工区'],['索引资料',fmt(totalFiles),'个文件'],['原始数据',totalBytes?fileSize(totalBytes):'—','本地引用'],['工区格式',`v${data.app.workspace_format}`,'自动原位迭代']].map(row=>`<div><span>${row[0]}</span><b>${row[1]}</b><small>${row[2]}</small></div>`).join('');
  document.querySelector('#hub-project-list').innerHTML=projects.map((project,index)=>`<button class="hub-project-card ${project.is_active?'active':''} ${project.exists===false?'missing':''}" data-hub-project="${index}" ${project.exists===false?'disabled':''}><div class="hub-project-visual"><span>${project.is_active?'CURRENT WORKSPACE':project.exists===false?'PATH OFFLINE':'PROJECT HISTORY'}</span></div><div class="hub-project-content"><header><div><h3>${esc(project.project_title||project.name)}</h3><p title="${esc(project.source_root||project.path||'')}">${esc(project.source_root||project.path||'临时分析状态')}</p></div><span class="hub-project-state ${project.is_active?'':'history'}">${project.is_active?'当前工区':project.version_current?'可打开':'待升级'}</span></header><div class="hub-project-metrics"><div><span>文件索引</span><b>${fmt(project.total_files||0)}</b></div><div><span>原始容量</span><b>${hubDataSize(project)}</b></div><div><span>代表样本</span><b>${fmt(project.representative_count||0)}</b></div></div><footer><b>.nvt v${project.format_version||'—'} · App ${esc(project.app_version||'—')}</b><span>${hubDate(project.scanned_at||project.updated_at,true)}</span><strong class="hub-project-enter">${project.is_active?'进入项目 →':'打开项目 →'}</strong></footer></div></button>`).join('')+`<button class="hub-project-card add-project" id="hub-add-project"><span>＋</span><b>打开其他分析工区</b><small>选择一个本机 .nvt 文件夹</small></button>`;
  document.querySelectorAll('[data-hub-project]').forEach(button=>button.onclick=()=>enterHubProject(projects[Number(button.dataset.hubProject)]));document.querySelector('#hub-add-project').onclick=()=>openWorkspaceFromHub();
