function hideProjectHub(){projectHub.classList.add('closed');document.body.classList.remove('project-hub-mode');navigate('project');requestAnimationFrame(()=>requestAnimationFrame(()=>{window.dispatchEvent(new Event('resize'));drawProjectMap();drawProject3d()}))}
