  document.querySelector('#well-group-count').textContent=`${fmt(groups.length)} 个`;
  list.innerHTML=groups.map(group=>`<div class="well-group-card ${String(group.id)===String(state.activeWellGroupId)?'active':''}" data-well-group-select="${group.id}"><span><b>${esc(group.name)}</b><small>${esc(group.description||'未填写说明')}</small></span><em>${fmt(group.member_count)} 井</em><div class="well-group-card-actions"><label title="参与合并预览"><input type="checkbox" data-well-group-merge="${group.id}"></label><button type="button" title="编辑井组" data-well-group-edit="${group.id}">✎</button><button type="button" title="删除井组" data-well-group-delete="${group.id}">×</button></div></div>`).join('')||'<div class="empty-state">尚未建立井组</div>';
