document.querySelector('#well-group-create').onclick=createWellGroup;document.querySelector('#well-group-well-search').oninput=renderWellGroupManager;document.querySelector('#well-group-select-filtered').onclick=()=>{if(!state.activeWellGroupId){toast('请先选择井组',true);return}wellGroupFilteredWells().forEach(well=>state.wellGroupDraftMembers.add(well.well_key));renderWellGroupManager()};document.querySelector('#well-group-clear-members').onclick=()=>{if(!state.activeWellGroupId)return;state.wellGroupDraftMembers.clear();renderWellGroupManager()};document.querySelector('#well-group-save-members').onclick=async()=>{const group=wellGroupById(state.activeWellGroupId);if(!group){toast('请先选择井组',true);return}try{const result=await api(`/api/well-groups/${group.id}/members`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({well_keys:[...state.wellGroupDraftMembers]})});state.deliveryGroupId=String(group.id);await refreshWellGroups(group.id);toast(`已保存 ${fmt(result.members)} 口井到“${group.name}”`)}catch(error){toast(error.message,true)}};document.querySelector('#well-group-preview').onclick=previewWellGroupMerge;
